import { existsSync } from "node:fs";
import { join } from "node:path";
import { site } from "../data/site";

// Open Graph card for a route. Cards live in public/og/<route>.jpg (generated by
// scripts/og-cards.mjs and committed). Falls back to the site card so og:image is never missing.
export const OG_SIZE = { width: 1200, height: 630 } as const;

export function ogCardPath(pathname: string): string {
  const route = pathname.replace(/\.html$/, "").replace(/(^|\/)index$/, "").replace(/^\/|\/$/g, "") || "index";
  const file = `/og/${route}.jpg`;
  return existsSync(join(process.cwd(), "public", file)) ? file : "/og/index.jpg";
}

export const ogCardUrl = (pathname: string) => new URL(ogCardPath(pathname), site.url).href;
